/**
 * EscalationContextHeader — server-generated explainer + tech identity + timestamps
 *
 * Location: apps/web/src/features/field-issues/components/EscalationContextHeader.tsx
 *
 * Established FE-B9. Renders explainer copy VERBATIM from server (RULE 4).
 * Never compute or rephrase the explainer — it is pre-generated by the backend.
 */

"use client";

import React, { useState } from "react";
import type { FieldIssueDetail } from "../types";

interface EscalationContextHeaderProps {
  issue: FieldIssueDetail;
  testID?: string;
}

function formatDateTime(iso: string): string {
  return new Date(iso).toLocaleString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    timeZoneName: "short",
  });
}

export function EscalationContextHeader({
  issue,
  testID,
}: EscalationContextHeaderProps) {
  const [isTimestampsExpanded, setIsTimestampsExpanded] = useState(false);

  return (
    <div
      className="space-y-4 rounded-md border border-neutral-200 bg-white p-6"
      data-testid={testID ?? "escalation-context-header"}
    >
      {/* Explainer copy — rendered verbatim from server (RULE 4) */}
      <p className="text-body text-neutral-900" data-testid="explainer-copy">
        {issue.explainerCopy}
      </p>

      {/* Tech identity row */}
      <div className="flex items-center gap-3" data-testid="tech-identity-row">
        <div className="flex h-8 w-8 items-center justify-center rounded-full bg-brand-100">
          <span className="text-caption font-medium text-brand-700">
            {issue.techName
              .split(" ")
              .map((n) => n[0])
              .join("")
              .slice(0, 2)
              .toUpperCase()}
          </span>
        </div>
        <div>
          <p className="text-body font-medium text-neutral-900">
            {issue.techName}
          </p>
          {issue.techLastActiveAt && (
            <p className="text-caption text-neutral-600">
              Last active {formatDateTime(issue.techLastActiveAt)}
            </p>
          )}
        </div>
      </div>

      {/* Collapsible timestamp details */}
      <div>
        <button
          type="button"
          onClick={() => setIsTimestampsExpanded(!isTimestampsExpanded)}
          className="flex items-center gap-1 text-caption text-neutral-600 hover:text-neutral-900"
          aria-expanded={isTimestampsExpanded}
          data-testid="timestamps-toggle"
        >
          <span>{isTimestampsExpanded ? "▾" : "▸"}</span>
          Timeline details
        </button>

        {isTimestampsExpanded && (
          <div
            className="mt-2 grid grid-cols-1 gap-2 rounded-md bg-neutral-50 p-3 sm:grid-cols-3"
            data-testid="timestamps-detail"
          >
            <div>
              <p className="text-caption font-medium text-neutral-600">
                Captured offline
              </p>
              <p className="text-caption text-neutral-900">
                {formatDateTime(issue.capturedAt)}
              </p>
            </div>
            <div>
              <p className="text-caption font-medium text-neutral-600">
                Sync attempted
              </p>
              <p className="text-caption text-neutral-900">
                {formatDateTime(issue.syncAttemptedAt)}
              </p>
            </div>
            <div>
              <p className="text-caption font-medium text-neutral-600">
                Escalated
              </p>
              <p className="text-caption text-neutral-900">
                {formatDateTime(issue.escalatedAt)}
              </p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
